import{_ as p,o as e,c as t,a3 as s}from"./chunks/framework.D3kUw6rp.js";const r="/assets/2014.F45FNZgl.jpeg",o="/assets/2015.BEu1x5Tu.jpeg",i="/assets/1.BjvJsDCA.jpeg",l="/assets/2017.vaV9TNvd.jpeg",n="/assets/2018.koEjLMJ4.jpeg",c="/assets/2019.DsySuRGk.jpeg",_="/assets/2020.CfIysL_N.jpeg",d="/assets/2020-2.CBfkmgBQ.jpeg",h="/assets/2021.pNBrTh4j.jpeg",m="/assets/2024.ljHSWS3J.jpeg",P=JSON.parse('{"title":"我的桌面","description":"","frontmatter":{"pageClass":"my-desktop"},"headers":[],"relativePath":"article/2024/desktop/index.md","filePath":"article/2024/desktop/index.md"}'),u={name:"article/2024/desktop/index.md"};function g(k,a,b,f,q,x){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="我的桌面" tabindex="-1">我的桌面 <a class="header-anchor" href="#我的桌面" aria-label="Permalink to &quot;我的桌面&quot;">​</a></h1><p>从小就喜欢给家里整理抽屉</p><p>删繁就简，重新摆放</p><p>秩序感比较强，小时候去山上砍柴火，堆放在家里都会码得整整齐齐</p><p>还会因为家人没有整齐摆放而生气</p><p>所以对于最可控的桌面，完全属于自己的领域，我有十足的折腾精神让自己满意</p><p>主要都是以简洁为主</p><p>下面简单列一下这 10 年的桌面演变</p><h3 id="_2014-年" tabindex="-1">2014 年 <a class="header-anchor" href="#_2014-年" aria-label="Permalink to &quot;2014 年&quot;">​</a></h3><p>毕业那年在学校附近的出租房，使用的是购买的二手 Thinkpad x201</p><p>全新的要一万多（通过破机器牵线从一个工程老板手上购买）</p><p>当时的桌面很简陋，最大的愿望就是能买个显示器</p><p><img src="'+r+'" alt=""></p><h3 id="_2015-年" tabindex="-1">2015 年 <a class="header-anchor" href="#_2015-年" aria-label="Permalink to &quot;2015 年&quot;">​</a></h3><p>还是使用那台 Thinkpad x201</p><p>购买了戴尔 U2414 显示器，把笔记本当作主机使用了</p><p>当时住在城中村下边社（如今已经是建发的楼盘）</p><p><img src="'+o+'" alt=""></p><h3 id="_2016-年" tabindex="-1">2016 年 <a class="header-anchor" href="#_2016-年" aria-label="Permalink to &quot;2016 年&quot;">​</a></h3><p>换工作到海沧，在石塘村的民租房</p><p>使用的是当时京东 618 活动 12 期免息购买的 MacBook 2015</p><p>这是最后一款 logo 会亮的 MacBook</p><p>至今（2024）依然还在家里当娱乐机使用</p><p>当时这个桌面是我最专注的时期，经常学习到深夜，第二天起床牙齿没刷继续写代码</p><p>当时沉迷于用原生 js 封装各种插件</p><p><img src="'+i+'" alt=""></p><h3 id="_2017-年" tabindex="-1">2017 年 <a class="header-anchor" href="#_2017-年" aria-label="Permalink to &quot;2017 年&quot;">​</a></h3><p>换工作到世贸双子塔</p><p>这应该算是拥有过的景观最好的桌面了</p><p>从双子塔 55 层，一眼望去就是大海，对望鼓浪屿的郑成功雕像</p><p><img src="'+l+'" alt=""></p><h3 id="_2018-年" tabindex="-1">2018 年 <a class="header-anchor" href="#_2018-年" aria-label="Permalink to &quot;2018 年&quot;">​</a></h3><p>在稿定科技，第一次尝试竖屏和升降桌</p><p>升降桌到现在（2024）依然是刚需，久坐太伤身了</p><p>升降桌的搭配当时在稿定也引领了一次风潮吧</p><p><img src="'+n+'" alt=""></p><h3 id="_2019-年" tabindex="-1">2019 年 <a class="header-anchor" href="#_2019-年" aria-label="Permalink to &quot;2019 年&quot;">​</a></h3><p>从热衷多块屏幕到尝试只使用一个 4K 显示器</p><p>想回归简约（我非常热衷于来回折腾桌面）</p><p>（没坚持多久，一块显示器很影响效率）</p><p><img src="'+c+'" alt=""></p><h3 id="_2020-年" tabindex="-1">2020 年 <a class="header-anchor" href="#_2020-年" aria-label="Permalink to &quot;2020 年&quot;">​</a></h3><p>在繁杂和简约中找到一个平衡点</p><p>4K 显示 + 笔记本屏幕 （上下布局）</p><p>我喜欢上下浏览，而不喜欢左右浏览</p><details class="details custom-block"><summary>题外话</summary><p>所以当显示器越做越宽的时候，我是悲观的</p><p>直到 2023 年，LG 才尝试推出一款 21:18 的显示器（适合上下分屏）</p></details><p><img src="'+_+'" alt=""></p><p>对显示器的防眩光能力特别在意</p><p>所以一直都是使用雾面屏（镜面屏对眼睛不友好）</p><p>对眩光的在意程度甚至让我购买了遮光罩（正常只有专业需求的人会使用）</p><p><img src="'+d+'" alt=""></p><h3 id="_2021-年-至今" tabindex="-1">2021 年 - 至今 <a class="header-anchor" href="#_2021-年-至今" aria-label="Permalink to &quot;2021 年 - 至今&quot;">​</a></h3><p>工位是半包围结构的，特别喜欢这样界限分明的办公桌</p><p>不容易被同事的杂乱影响到</p><p>排列方式是我折腾多次得到的最优解，脖子几乎没有酸痛过了</p><p><img src="'+h+'" alt=""></p><h3 id="小书房" tabindex="-1">小书房 <a class="header-anchor" href="#小书房" aria-label="Permalink to &quot;小书房&quot;">​</a></h3><p>整个家只有这张桌子的空间是完全属于自己的，偶尔会被玥玥搞乱，等她长大了可能要给她写作业了，我又没有自己的空间。</p><p><img src="'+m+'" alt=""></p><p>未完待续...</p><p>关于桌面搭配我有很多话说，只是不知道从哪里说起，以后有机会写一篇长篇文字</p>',61)])])}const T=p(u,[["render",g]]);export{P as __pageData,T as default};
